    ('a4100000-0000-4000-8000-000000000006', 'c0000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', 'a2100000-0000-4000-8000-000000000003', 'a3100000-0000-4000-8000-000000000003', 'd0000000-0000-0000-0000-000000000001', 'A block of mass m rests in a lift accelerating up with a. The normal force is:', 'MEDIUM', 4, 1, 60, 2021, 'ORIGINAL_BANK', 'MedyCatalog original · 2016-2025 syllabus coverage', 'en', 'PUBLISHED', NULL),
    ('a4100000-0000-4000-8000-000000000007', 'c0000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', 'a2100000-0000-4000-8000-000000000004', 'a3100000-0000-4000-8000-000000000004', 'd0000000-0000-0000-0000-000000000001', 'Work done by a conservative force around a closed path is:', 'EASY', 4, 1, 60, 2022, 'ORIGINAL_BANK', 'MedyCatalog original · 2016-2025 syllabus coverage', 'en', 'PUBLISHED', NULL),
    ('a4100000-0000-4000-8000-000000000008', 'c0000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', 'a2100000-0000-4000-8000-000000000004', 'a3100000-0000-4000-8000-000000000004', 'd0000000-0000-0000-0000-000000000001', 'Instantaneous power delivered by force F is:', 'EASY', 4, 1, 60, 2023, 'ORIGINAL_BANK', 'MedyCatalog original · 2016-2025 syllabus coverage', 'en', 'PUBLISHED', NULL),
