INSERT INTO question_explanations (id, question_id, simple_text, detailed_text, why_others_wrong, related_concept_topic_id, exam_tip) VALUES
    ('a6100000-0000-4000-8000-000000000001', 'a4100000-0000-4000-8000-000000000001', 'Force is mass times acceleration.', 'F = ma. Acceleration is L T^-2, so M L T^-2. Energy is M L^2 T^-2.', 'Momentum is M L T^-1; energy has an extra length.', 'a3100000-0000-4000-8000-000000000001', 'Write the defining equation first, then dimensions.'),
    ('a6100000-0000-4000-8000-000000000002', 'a4100000-0000-4000-8000-000000000002', 'Errors add for sums.', 'For sum/difference, absolute errors add: 0.1+0.1=0.2.', 'Products use relative errors.', 'a3100000-0000-4000-8000-000000000001', 'Never subtract errors for a sum.'),
    ('a6100000-0000-4000-8000-000000000003', 'a4100000-0000-4000-8000-000000000003', 'u = 0 so s = ½at².', 'Substitute u=0 in s = ut + ½at².', 'vt is for uniform velocity.', 'a3100000-0000-4000-8000-000000000002', 'List u, a, t before choosing a formula.'),
    ('a6100000-0000-4000-8000-000000000004', 'a4100000-0000-4000-8000-000000000004', 'a = dv/dt, the slope.', 'Area under v–t is displacement; slope is acceleration.', 'Jerk is da/dt.', 'a3100000-0000-4000-8000-000000000002', 'Read axes before reading slope.'),
    ('a6100000-0000-4000-8000-000000000005', 'a4100000-0000-4000-8000-000000000005', 'f_max = μN and N = mg.', 'N = mg when the surface is horizontal and no other vertical force acts.', 'μ/mg is dimensionally wrong.', 'a3100000-0000-4000-8000-000000000003', 'Draw N before writing friction.'),
    ('a6100000-0000-4000-8000-000000000006', 'a4100000-0000-4000-8000-000000000006', 'Non-inertial: apparent weight m(g+a).', 'Net F_up = N − mg = ma, so N = m(g+a).', 'g−a is for downward acceleration.', 'a3100000-0000-4000-8000-000000000003', 'Take upward positive consistently.'),
    ('a6100000-0000-4000-8000-000000000007', 'a4100000-0000-4000-8000-000000000007', 'Conservative ⇔ path independent ⇔ closed-path work 0.', 'Electrostatic and gravity are conservative (in usual intro models).', 'Friction is not conservative.', 'a3100000-0000-4000-8000-000000000004', 'If work around a loop is not zero, the force is non-conservative.'),
    ('a6100000-0000-4000-8000-000000000008', 'a4100000-0000-4000-8000-000000000008', 'P = dW/dt = F·v.', 'Dot product: only the parallel component of F does work.', 'F/t is not power.', 'a3100000-0000-4000-8000-000000000004', 'Check watts = newton × metre/second.'),
    ('a6100000-0000-4000-8000-000000000009', 'a4100000-0000-4000-8000-000000000009', 'Gaussian surface inside: q_enc = 0 so E = 0.', 'Outside it behaves like a point charge.', 'σ/ε0 is a conductor surface just outside.', 'a3100000-0000-4000-8000-000000000005', 'Use Gauss only with matching symmetry.'),
    ('a6100000-0000-4000-8000-000000000010', 'a4100000-0000-4000-8000-000000000010', 'Coulomb force is repulsive for like signs.', 'Direction is central, along the line joining charges.', 'Gravity is always attractive.', 'a3100000-0000-4000-8000-000000000005', 'Sign of q1 q2 sets attraction vs repulsion.'),
    ('a6100000-0000-4000-8000-000000000011', 'a4100000-0000-4000-8000-000000000011', 'Charge is conserved so current is the same in series.', 'Voltages add to the battery emf.', 'Power is I²R, larger on larger R.', 'a3100000-0000-4000-8000-000000000006', 'Draw the single loop before assigning I.'),
    ('a6100000-0000-4000-8000-000000000012', 'a4100000-0000-4000-8000-000000000012', 'ΣI = 0 because charge does not pile up.', 'The loop rule is energy per unit charge.', 'Ohm is a material relation.', 'a3100000-0000-4000-8000-000000000006', 'Write current arrows first, then signs.'),
    ('a6100000-0000-4000-8000-000000000013', 'a4100000-0000-4000-8000-000000000013', 'Convex (converging) lens: positive focal length in the Cartesian convention used in JEE.', 'Concave lens diverges (f < 0).', 'Real images occur when the object is outside F.', 'a3100000-0000-4000-8000-000000000007', 'Power is 1/f, not zero.'),
    ('a6100000-0000-4000-8000-000000000014', 'a4100000-0000-4000-8000-000000000014', 'sin c = n2/n1 = 1/1.5.', 'Light goes glass → air, so n1=1.5, n2=1.', '1.5 would be > 1, impossible for sine.', 'a3100000-0000-4000-8000-000000000007', 'TIR needs denser to rarer.'),
    ('a6100000-0000-4000-8000-000000000015', 'a4100000-0000-4000-8000-000000000015', 'More photons per second → more electrons per second → larger current.', 'K_max depends on frequency, not intensity.', 'Work function is a material property.', 'a3100000-0000-4000-8000-000000000008', 'Threshold is about ν, not brightness.'),
    ('a6100000-0000-4000-8000-000000000016', 'a4100000-0000-4000-8000-000000000016', 'φ is the binding energy of the least-bound electron.', 'K_max = hν − φ.', 'Stopping potential measures K_max.', 'a3100000-0000-4000-8000-000000000008', 'Do not confuse φ with V0.'),
    ('a6100000-0000-4000-8000-000000000017', 'a4100000-0000-4000-8000-000000000017', 'l = 0,1,2,…,n−1 so 0,1,2 for n=3 (s,p,d).', 'l cannot equal n.', '3d is l=2, n=3.', 'a3100000-0000-4000-8000-000000000009', 'Write n first, then l max = n−1.'),
    ('a6100000-0000-4000-8000-000000000018', 'a4100000-0000-4000-8000-000000000018', 'At most one electron per unique (n,l,m_l,m_s).', 'Two electrons in 1s have opposite spins.', 'Hund is about degenerate orbitals.', 'a3100000-0000-4000-8000-000000000009', 'Pauli is not a statement about n alone.'),
    ('a6100000-0000-4000-8000-000000000019', 'a4100000-0000-4000-8000-000000000019', 'Five bond pairs, no lone pair → TBP.', 'PCl3 is pyramidal; SF6 is octahedral.', 'Linear is two domains.', 'a3100000-0000-4000-8000-000000000010', 'Count domains on the central atom.'),
    ('a6100000-0000-4000-8000-000000000020', 'a4100000-0000-4000-8000-000000000020', 'Four domains (2 bond + 2 lp) → tetrahedral arrangement, molecular shape bent.', 'Oxygen is sp3, not sp.', 'H-bonding affects boiling point, not the H–O–H angle origin.', 'a3100000-0000-4000-8000-000000000010', 'Start from AX2E2.'),
    ('a6100000-0000-4000-8000-000000000021', 'a4100000-0000-4000-8000-000000000021', 'Catalysts change rate, not the equilibrium constant.', 'ΔG° = −RT ln K is a state function of T, not of path.', 'K changes with T, not with catalyst.', 'a3100000-0000-4000-8000-000000000011', 'Separate kinetics from thermodynamics.'),
    ('a6100000-0000-4000-8000-000000000022', 'a4100000-0000-4000-8000-000000000022', 'Fewer gas moles on the product side (4 → 2), so high P favours NH3.', 'Le Chatelier: system reduces pressure by forming fewer molecules.', 'K itself is not changed by P (ideal gases) but composition is.', 'a3100000-0000-4000-8000-000000000011', 'Count Δn_g first.'),
    ('a6100000-0000-4000-8000-000000000023', 'a4100000-0000-4000-8000-000000000023', 'Same formula, Cl at different carbons → position isomerism.', 'Enantiomers are non-superimposable mirror images.', 'Metamers differ in alkyl groups on either side of a divalent function.', 'a3100000-0000-4000-8000-000000000012', 'Compare the locant of the functional group.'),
    ('a6100000-0000-4000-8000-000000000024', 'a4100000-0000-4000-8000-000000000024', 'Tertiary is most stabilised by alkyl hyperconjugation/induction.', 'Methyl has no alkyl donors.', 'Allylic/benzylic can rival 3° but are not in this list.', 'a3100000-0000-4000-8000-000000000012', 'More hyperconjugative structures → more stable.'),
    ('a6100000-0000-4000-8000-000000000025', 'a4100000-0000-4000-8000-000000000025', 'Bond energy of N≡N is very high.', 'P4 has strained P–P bonds and is more reactive in white phosphorus.', 'Nitrogen is a non-metal gas.', 'a3100000-0000-4000-8000-000000000013', 'Nitrogen has no 2d orbitals.'),
    ('a6100000-0000-4000-8000-000000000026', 'a4100000-0000-4000-8000-000000000026', 'Heavier p-block: ns² electrons remain inert; Bi prefers +3.', 'B and C are light.', 'Oxygen is group 16 period 2.', 'a3100000-0000-4000-8000-000000000013', 'Look to the bottom of groups 13–15.'),
    ('a6100000-0000-4000-8000-000000000027', 'a4100000-0000-4000-8000-000000000027', 'Factor (x−1)(x−3)=0.', 'Sum 4, product 3.', '−1 and −3 would need sum −4.', 'a3100000-0000-4000-8000-000000000014', 'Check product and sum against options.'),
    ('a6100000-0000-4000-8000-000000000028', 'a4100000-0000-4000-8000-000000000028', 'Negative discriminant → non-real conjugates.', 'Equal real needs D=0.', 'A quadratic has exactly two roots in ℂ, counting multiplicity.', 'a3100000-0000-4000-8000-000000000014', 'State the coefficient field (real) before concluding conjugates.'),
    ('a6100000-0000-4000-8000-000000000029', 'a4100000-0000-4000-8000-000000000029', 'a=3, d=4, a10=3+9×4=39.', 'Formula a+(n−1)d.', '40 would be if someone used n d.', 'a3100000-0000-4000-8000-000000000015', 'Count (n−1) steps, not n.'),
    ('a6100000-0000-4000-8000-000000000030', 'a4100000-0000-4000-8000-000000000030', 'a=1, r=1/2, S=a/(1−r)=2.', '|r|<1 is required for convergence.', 'Partial sums approach 2, not 1.', 'a3100000-0000-4000-8000-000000000015', 'Write |r| before summing to infinity.'),
    ('a6100000-0000-4000-8000-000000000031', 'a4100000-0000-4000-8000-000000000031', 'Write (sin 5x)/(5x) × 5 → 1×5=5.', 'x must be radians.', 'sin 5x / x is not 1.', 'a3100000-0000-4000-8000-000000000016', 'Factor the angle coefficient.'),
    ('a6100000-0000-4000-8000-000000000032', 'a4100000-0000-4000-8000-000000000032', 'Power rule n x^{n−1}.', 'Integral of x³ is x⁴/4, not the derivative.', '3x³ would be if exponent stayed.', 'a3100000-0000-4000-8000-000000000016', 'Bring the power down, then reduce the power by 1.'),
    ('a6100000-0000-4000-8000-000000000033', 'a4100000-0000-4000-8000-000000000033', 'Antiderivative x² from 0 to 1 is 1.', 'This is the area of a triangle of base 1 height 2, which is 1.', '2 would be if you forgot to divide in geometry.', 'a3100000-0000-4000-8000-000000000017', 'Evaluate F(b)−F(a), do not drop limits.'),
    ('a6100000-0000-4000-8000-000000000034', 'a4100000-0000-4000-8000-000000000034', 'x³ is odd and the interval is symmetric.', 'The two areas cancel.', 'x² is even, not x³.', 'a3100000-0000-4000-8000-000000000017', 'Check f(−x) before integrating across zero.'),
    ('a6100000-0000-4000-8000-000000000035', 'a4100000-0000-4000-8000-000000000035', 'Independent ⇒ product 1/6.', '5/6 would be a naive union without inclusion-exclusion.', '0 would be mutually exclusive.', 'a3100000-0000-4000-8000-000000000018', 'Independent ≠ mutually exclusive.'),
    ('a6100000-0000-4000-8000-000000000036', 'a4100000-0000-4000-8000-000000000036', 'Definition of conditional probability.', 'P(B|A) is the reverse conditional.', 'Always condition on the event after the bar.', 'a3100000-0000-4000-8000-000000000018', 'Draw a two-way table for Bayes problems.'),
    ('a6100000-0000-4000-8000-000000000037', 'a4100000-0000-4000-8000-000000000037', 'sin2θ = 1 ⇒ 2θ=90° ⇒ θ=45°.', '30° and 60° share a smaller range.', '90° is vertical, range 0.', 'a3100000-0000-4000-8000-000000000019', 'Level ground and no air are required for 45°.'),
    ('a6100000-0000-4000-8000-000000000038', 'a4100000-0000-4000-8000-000000000038', 'No horizontal force ⇒ no horizontal acceleration.', 'Vertical component changes due to gravity.', 'Zero only if thrown vertically.', 'a3100000-0000-4000-8000-000000000019', 'Resolve before applying equations.'),
    ('a6100000-0000-4000-8000-000000000039', 'a4100000-0000-4000-8000-000000000039', 'v_esc = √(2GM/R), no m of projectile.', 'Heavier planets or smaller R increase escape speed.', 'G is in the formula.', 'a3100000-0000-4000-8000-000000000020', 'Energy cancels m.'),
    ('a6100000-0000-4000-8000-000000000040', 'a4100000-0000-4000-8000-000000000040', 'Centripetal acceleration GM/r² toward the planet.', 'Speed can be constant while velocity (vector) changes.', 'This is why it does not fly off tangentially.', 'a3100000-0000-4000-8000-000000000020', 'Acceleration can be perpendicular to velocity.'),
    ('a6100000-0000-4000-8000-000000000041', 'a4100000-0000-4000-8000-000000000041', 'R ∝ L/A → 2 / (1/2) = 4.', 'Resistivity unchanged if temperature is same.', 'Half would invert the proportion.', 'a3100000-0000-4000-8000-000000000021', 'Write R=ρL/A before plugging numbers.'),
    ('a6100000-0000-4000-8000-000000000042', 'a4100000-0000-4000-8000-000000000042', '1/Req = 3/R ⇒ Req=R/3.', 'Series would be 3R.', 'Parallel always ≤ the smallest branch.', 'a3100000-0000-4000-8000-000000000021', 'More parallel paths, smaller Req.'),
    ('a6100000-0000-4000-8000-000000000043', 'a4100000-0000-4000-8000-000000000043', 'Diverging (concave) lens.', 'Hypermetropia uses convex.', 'Cylindrical mainly for astigmatism.', 'a3100000-0000-4000-8000-000000000022', 'Match defect to whether the image falls in front or behind the retina.'),
    ('a6100000-0000-4000-8000-000000000044', 'a4100000-0000-4000-8000-000000000044', '1 D = 1 m⁻¹.', 'f must be in metres: P=1/f.', 'Candela is luminous intensity.', 'a3100000-0000-4000-8000-000000000022', 'Sign of P follows sign of f.'),
    ('a6100000-0000-4000-8000-000000000045', 'a4100000-0000-4000-8000-000000000045', 'Both electrons in the shared pair come from one atom.', 'After formation it behaves like an ordinary covalent bond.', 'H-bond is intermolecular.', 'a3100000-0000-4000-8000-000000000023', 'Look for Lewis bases (lone pairs).'),
    ('a6100000-0000-4000-8000-000000000046', 'a4100000-0000-4000-8000-000000000046', 'Mobile Na+ and Cl− carry current.', 'Solid NaCl has ions locked in the lattice, so it does not conduct.', 'Metals use delocalised electrons.', 'a3100000-0000-4000-8000-000000000023', 'State of matter matters for ionic conductors.'),
    ('a6100000-0000-4000-8000-000000000047', 'a4100000-0000-4000-8000-000000000047', '[H+]=10⁻³ so pH=3.', 'pH 1 would be 0.1 M.', 'Do not take −log of molarity without checking complete ionisation.', 'a3100000-0000-4000-8000-000000000024', '10^{-pH} = [H+] for strong monoprotic acids (dilute).'),
    ('a6100000-0000-4000-8000-000000000048', 'a4100000-0000-4000-8000-000000000048', 'Weak acid + its salt (conjugate base).', 'HCl/NaCl is not a buffer; HCl is strong.', 'NaOH alone is a strong base.', 'a3100000-0000-4000-8000-000000000024', 'Need a conjugate pair.'),
    ('a6100000-0000-4000-8000-000000000049', 'a4100000-0000-4000-8000-000000000049', 'Peptide (amide) −CO−NH−.', 'Glycosidic joins sugars; phosphodiester joins nucleotides.', 'Ionic bonds may stabilise tertiary structure but are not the backbone.', 'a3100000-0000-4000-8000-000000000025', 'Backbone = peptide; side chains vary.'),
    ('a6100000-0000-4000-8000-000000000050', 'a4100000-0000-4000-8000-000000000050', 'Starch has α links; cellulose has β-1,4.', 'It is a polysaccharide, not a protein.', 'Herbivores often rely on microbes.', 'a3100000-0000-4000-8000-000000000025', 'Link structure to enzyme specificity.'),
    ('a6100000-0000-4000-8000-000000000051', 'a4100000-0000-4000-8000-000000000051', 'C=C is the site of addition (H2, Br2, HBr, H2O).', 'Benzene substitutes to keep the aromatic sextet.', 'Alkanes more often substitute.', 'a3100000-0000-4000-8000-000000000026', 'Identify the functional multiple bond first.'),
    ('a6100000-0000-4000-8000-000000000052', 'a4100000-0000-4000-8000-000000000052', 'H adds to CH2, Br to the CH (more substituted carbon).', 'Peroxides reverse this for HBr only.', 'Propane would be hydrogenation.', 'a3100000-0000-4000-8000-000000000026', 'Draw the two possible carbocations.'),
    ('a6100000-0000-4000-8000-000000000053', 'a4100000-0000-4000-8000-000000000053', 'Endosymbiotic organelles and bacteria have 70S.', 'Cytosolic eukaryotic ribosomes are 80S.', 'This supports the endosymbiotic theory.', 'a3100000-0000-4000-8000-000000000027', 'S is a sedimentation coefficient, not mass directly.'),
    ('a6100000-0000-4000-8000-000000000054', 'a4100000-0000-4000-8000-000000000054', 'Golgi modifies and packages for secretion or lysosomes.', 'Ribosomes synthesise; they do not package.', 'Nucleolus is rRNA/ribosome assembly.', 'a3100000-0000-4000-8000-000000000027', 'Follow RER → Golgi → vesicle.'),
    ('a6100000-0000-4000-8000-000000000055', 'a4100000-0000-4000-8000-000000000055', 'Photolysis of H2O at PSII.', 'Rubisco uses CO2 carbon for sugar, not as the O2 source.', 'Van Niel and later isotope work established this.', 'a3100000-0000-4000-8000-000000000028', 'Light reaction vs Calvin: know where each product is made.'),
    ('a6100000-0000-4000-8000-000000000056', 'a4100000-0000-4000-8000-000000000056', 'Stroma of the chloroplast.', 'Light reactions are on thylakoid membranes.', 'Matrix is Krebs cycle.', 'a3100000-0000-4000-8000-000000000028', 'Map compartment to process.'),
    ('a6100000-0000-4000-8000-000000000057', 'a4100000-0000-4000-8000-000000000057', 'Unknown × recessive; 1:1 means the unknown was heterozygous.', 'Crossing two heterozygotes is an F2, not a test cross.', 'Independent assortment needs two genes on different chromosomes (or far apart).', 'a3100000-0000-4000-8000-000000000029', 'Write gametes in a Punnett square.'),
    ('a6100000-0000-4000-8000-000000000058', 'a4100000-0000-4000-8000-000000000058', 'A–T (two H-bonds), G–C (three).', 'Uracil replaces thymine in RNA (A–U).', 'Purine pairs with pyrimidine, keeping width constant.', 'a3100000-0000-4000-8000-000000000029', 'Chargaff: A=T and G=C in duplex DNA.'),
    ('a6100000-0000-4000-8000-000000000059', 'a4100000-0000-4000-8000-000000000059', 'Second law: inefficient transfer, often ~10%.', 'Number pyramids can invert (tree vs insects).', 'Decomposers act at all levels.', 'a3100000-0000-4000-8000-000000000030', 'Follow energy, not just head-counts.'),
    ('a6100000-0000-4000-8000-000000000060', 'a4100000-0000-4000-8000-000000000060', 'In-situ: conserve in the natural habitat.', 'Zoos/seed banks are ex-situ.', 'Both strategies are used together.', 'a3100000-0000-4000-8000-000000000030', 'Match the method to whether organisms stay in habitat.'),
    ('a6100000-0000-4000-8000-000000000061', 'a4100000-0000-4000-8000-000000000061', 'Triple fusion: two polar nuclei + one male gamete → 3n.', 'Zygote is 2n.', 'This is unique to angiosperms.', 'a3100000-0000-4000-8000-000000000031', 'Track each male gamete.'),
    ('a6100000-0000-4000-8000-000000000062', 'a4100000-0000-4000-8000-000000000062', 'Pollination ≠ fertilisation (which is gamete fusion).', 'Germination of pollen is tube growth after landing.', 'Fruit dispersal moves seeds.', 'a3100000-0000-4000-8000-000000000031', 'Sequence: pollination → fertilisation → seed.'),
    ('a6100000-0000-4000-8000-000000000063', 'a4100000-0000-4000-8000-000000000063', 'Emulsification increases surface area for lipase.', 'Bile is not a hydrolase enzyme.', 'Pepsin/trypsin hydrolyse proteins.', 'a3100000-0000-4000-8000-000000000032', 'Liver/gall bladder vs pancreas roles.'),
    ('a6100000-0000-4000-8000-000000000064', 'a4100000-0000-4000-8000-000000000064', 'Zymogen activation by acid/pepsin is a safety mechanism.', 'Salivary amylase acts on starch in the mouth.', 'Inactive precursors are common for proteases.', 'a3100000-0000-4000-8000-000000000032', 'Name the organ and the substrate together.'),
    ('a6100000-0000-4000-8000-000000000065', 'a4100000-0000-4000-8000-000000000065', 'Sino-atrial node fires fastest and drives the rest.', 'AV node delays so atria finish contracting.', 'Purkinje fibres spread ventricular excitation.', 'a3100000-0000-4000-8000-000000000033', 'Sequence: SA → AV → bundle → Purkinje.'),
    ('a6100000-0000-4000-8000-000000000066', 'a4100000-0000-4000-8000-000000000066', 'Exception: pulmonary veins are oxygen-rich.', 'Pulmonary arteries are oxygen-poor, to lungs.', 'Name vessel by where it goes, then oxygenation.', 'a3100000-0000-4000-8000-000000000033', 'Left atrium receives pulmonary veins.'),
    ('a6100000-0000-4000-8000-000000000067', 'a4100000-0000-4000-8000-000000000067', 'Voltage-gated Na+ channels open; Na+ enters.', 'K+ exit dominates repolarisation.', 'Ca2+ is crucial at the synaptic terminal for vesicle release.', 'a3100000-0000-4000-8000-000000000034', 'Separate axon spike from synaptic transmission.'),
    ('a6100000-0000-4000-8000-000000000068', 'a4100000-0000-4000-8000-000000000068', 'Most CNS synapses are chemical.', 'Electrical synapses use gap junctions.', 'Hormones are endocrine, slower and broadcast.', 'a3100000-0000-4000-8000-000000000034', 'Cleft + receptor = chemical synapse.'),
    ('a6100000-0000-4000-8000-000000000069', 'a4100000-0000-4000-8000-000000000069', 'Mid-cycle LH surge.', 'FSH also rises but LH is the classic trigger.', 'hCG later mimics LH to keep the corpus luteum.', 'a3100000-0000-4000-8000-000000000035', 'Map hormone to day of the cycle.'),
    ('a6100000-0000-4000-8000-000000000070', 'a4100000-0000-4000-8000-000000000070', 'Ampullary region of the oviduct.', 'Implantation is uterine.', 'Ovary releases the oocyte; it is not the fusion site.', 'a3100000-0000-4000-8000-000000000035', 'Track gamete meeting place vs embedding place.'),
    ('a6100000-0000-4000-8000-000000000071', 'a4100000-0000-4000-8000-000000000071', 'Same function (flight), different structural origin → analogous.', 'Forelimbs of bat and whale are homologous.', 'Analogy is convergent evolution.', 'a3100000-0000-4000-8000-000000000036', 'Ask: common ancestor structure or common function?'),
    ('a6100000-0000-4000-8000-000000000072', 'a4100000-0000-4000-8000-000000000072', 'Selection filters phenotypes; genes are what is inherited.', 'Acquired characters are not generally encoded in germline DNA.', 'Populations evolve, not single organisms in one lifetime.', 'a3100000-0000-4000-8000-000000000036', 'Variation must be heritable.'),
    ('a6100000-0000-4000-8000-000000000073', 'a4100000-0000-4000-8000-000000000073', 'Common cold is viral; antibiotics target prokaryotic biochemistry.', 'Misuse drives resistance.', 'Antivirals are a different drug class.', 'a3100000-0000-4000-8000-000000000037', 'Identify the pathogen type first.'),
    ('a6100000-0000-4000-8000-000000000074', 'a4100000-0000-4000-8000-000000000074', 'Memory B/T cells respond faster on re-exposure.', 'It is acquired immunity, not an antibiotic dose.', 'Herd immunity appears when coverage is high.', 'a3100000-0000-4000-8000-000000000037', 'Antigen without full disease is the idea of most vaccines.'),
    ('a6100000-0000-4000-8000-000000000075', 'a4100000-0000-4000-8000-000000000075', 'Proximal convoluted tubule has transporters for glucose.', 'Glomerulus filters; it does not selectively reabsorb.', 'Glycosuria when threshold is exceeded (e.g. diabetes).', 'a3100000-0000-4000-8000-000000000038', 'Filtration vs reabsorption vs secretion.'),
    ('a6100000-0000-4000-8000-000000000076', 'a4100000-0000-4000-8000-000000000076', 'Aquaporins in collecting-duct cells.', 'Without ADH, large volumes of dilute urine (diabetes insipidus).', 'Bladder stores urine, does not fine-tune osmolarity.', 'a3100000-0000-4000-8000-000000000038', 'Link hormone to the segment.'),
    ('a6100000-0000-4000-8000-000000000077', 'a4100000-0000-4000-8000-000000000077', '3x=15, x=5.', 'Add 7 then divide by 3.', 'Do not divide only part of an expression.', 'a3100000-0000-4000-8000-000000000039', 'Inverse operations in reverse order.'),
    ('a6100000-0000-4000-8000-000000000078', 'a4100000-0000-4000-8000-000000000078', 'Parallel inconsistent lines.', 'Same left side, different right side.', 'Infinitely many would need the same line twice.', 'a3100000-0000-4000-8000-000000000039', 'Compare coefficients and constants.'),
    ('a6100000-0000-4000-8000-000000000079', 'a4100000-0000-4000-8000-000000000079', '1/2 + 1/2 = 1.', 'cos 60° = sin 30° = 1/2.', '√3 is sin 60° or tan 60° related.', 'a3100000-0000-4000-8000-000000000040', 'Memorise the 30-45-60 triangle.'),
    ('a6100000-0000-4000-8000-000000000080', 'a4100000-0000-4000-8000-000000000080', 'Pythagorean identity.', '1 + tan² = sec² is a different form.', 'Rearrange the identity you know rather than inventing one.', 'a3100000-0000-4000-8000-000000000040', 'sin²+cos²=1 is the seed identity.'),
    ('a6100000-0000-4000-8000-000000000081', 'a4100000-0000-4000-8000-000000000081', 'Sorted already; middle of five is the third value, 9.', '8.4 is the mean.', 'Do not average all five for the median.', 'a3100000-0000-4000-8000-000000000041', 'Sort first if needed.'),
    ('a6100000-0000-4000-8000-000000000082', 'a4100000-0000-4000-8000-000000000082', 'Mean uses every value, so tails pull it.', 'Median resists outliers.', 'Choose the average that matches the question’s robustness need.', 'a3100000-0000-4000-8000-000000000041', 'Sketch a dot plot.'),
    ('a6100000-0000-4000-8000-000000000083', 'a4100000-0000-4000-8000-000000000083', 'g_Moon ≈ g_Earth/6, so weight drops; mass is unchanged.', 'The Moon has gravity — that is why there is some weight.', 'Inertia depends on mass.', 'a3100000-0000-4000-8000-000000000042', 'Separate mass (kg) from weight (N).'),
    ('a6100000-0000-4000-8000-000000000084', 'a4100000-0000-4000-8000-000000000084', 'p = mv, vector along velocity.', '½mv² is kinetic energy (scalar).', 'Impulse changes momentum.', 'a3100000-0000-4000-8000-000000000042', 'Check units: kg·m/s.'),
    ('a6100000-0000-4000-8000-000000000085', 'a4100000-0000-4000-8000-000000000085', 'Acids turn blue litmus red.', 'Bases turn red litmus blue.', 'Neutral salts of SA/SB are near pH 7.', 'a3100000-0000-4000-8000-000000000043', 'Keep a two-row litmus table.'),
    ('a6100000-0000-4000-8000-000000000086', 'a4100000-0000-4000-8000-000000000086', 'Vinegar is dilute ethanoic (acetic) acid.', 'HCl/H2SO4/HNO3 are strong mineral acids.', 'Weak ≠ dilute; vinegar is both weak and typically dilute.', 'a3100000-0000-4000-8000-000000000043', 'Name the household source.'),
    ('a6100000-0000-4000-8000-000000000087', 'a4100000-0000-4000-8000-000000000087', 'Hb in erythrocytes.', 'A little O2 dissolves in plasma.', 'Platelets clot; WBC defend.', 'a3100000-0000-4000-8000-000000000044', 'Structure (Hb) matches function (O2 transport).'),
    ('a6100000-0000-4000-8000-000000000088', 'a4100000-0000-4000-8000-000000000088', 'Millions of thin-walled sacs, rich capillaries.', 'Trachea has cartilage and cilia for a different job.', 'Fick’s law: rate ∝ area / thickness.', 'a3100000-0000-4000-8000-000000000044', 'Match structure to diffusion.'),
    ('a6100000-0000-4000-8000-000000000089', 'a4100000-0000-4000-8000-000000000089', 'Female Anopheles carries Plasmodium.', 'Housefly is more typhoid/dysentery mechanically.', 'Know pathogen vs vector.', 'a3100000-0000-4000-8000-000000000045', 'Vector control is part of prevention.'),
    ('a6100000-0000-4000-8000-000000000090', 'a4100000-0000-4000-8000-000000000090', 'Obligate intracellular parasites.', 'Bacteria can be free-living or pathogenic.', 'Antibiotics typically fail on viruses.', 'a3100000-0000-4000-8000-000000000045', 'Host machinery is hijacked.');
INSERT INTO explanation_steps (id, question_id, step_order, title, body) VALUES
    ('a7100000-0000-4000-8000-000000000001', 'a4100000-0000-4000-8000-000000000001', 1, 'Idea', 'Force is mass times acceleration.'),
    ('a7100000-0000-4000-8000-000000000002', 'a4100000-0000-4000-8000-000000000001', 2, 'Why', 'F = ma. Acceleration is L T^-2, so M L T^-2. Energy is M L^2 T^-2.'),
    ('a7100000-0000-4000-8000-000000000003', 'a4100000-0000-4000-8000-000000000001', 3, 'Answer', '[M L T^-2]'),
    ('a7100000-0000-4000-8000-000000000004', 'a4100000-0000-4000-8000-000000000002', 1, 'Idea', 'Errors add for sums.'),
    ('a7100000-0000-4000-8000-000000000005', 'a4100000-0000-4000-8000-000000000002', 2, 'Why', 'For sum/difference, absolute errors add: 0.1+0.1=0.2.'),
    ('a7100000-0000-4000-8000-000000000006', 'a4100000-0000-4000-8000-000000000002', 3, 'Answer', '0.2'),
    ('a7100000-0000-4000-8000-000000000007', 'a4100000-0000-4000-8000-000000000003', 1, 'Idea', 'u = 0 so s = ½at².'),
    ('a7100000-0000-4000-8000-000000000008', 'a4100000-0000-4000-8000-000000000003', 2, 'Why', 'Substitute u=0 in s = ut + ½at².'),
    ('a7100000-0000-4000-8000-000000000009', 'a4100000-0000-4000-8000-000000000003', 3, 'Answer', '½at²'),
    ('a7100000-0000-4000-8000-000000000010', 'a4100000-0000-4000-8000-000000000004', 1, 'Idea', 'a = dv/dt, the slope.'),
    ('a7100000-0000-4000-8000-000000000011', 'a4100000-0000-4000-8000-000000000004', 2, 'Why', 'Area under v–t is displacement; slope is acceleration.'),
    ('a7100000-0000-4000-8000-000000000012', 'a4100000-0000-4000-8000-000000000004', 3, 'Answer', 'Acceleration'),
    ('a7100000-0000-4000-8000-000000000013', 'a4100000-0000-4000-8000-000000000005', 1, 'Idea', 'f_max = μN and N = mg.'),
    ('a7100000-0000-4000-8000-000000000014', 'a4100000-0000-4000-8000-000000000005', 2, 'Why', 'N = mg when the surface is horizontal and no other vertical force acts.'),
    ('a7100000-0000-4000-8000-000000000015', 'a4100000-0000-4000-8000-000000000005', 3, 'Answer', 'μmg'),
    ('a7100000-0000-4000-8000-000000000016', 'a4100000-0000-4000-8000-000000000006', 1, 'Idea', 'Non-inertial: apparent weight m(g+a).'),
    ('a7100000-0000-4000-8000-000000000017', 'a4100000-0000-4000-8000-000000000006', 2, 'Why', 'Net F_up = N − mg = ma, so N = m(g+a).'),
    ('a7100000-0000-4000-8000-000000000018', 'a4100000-0000-4000-8000-000000000006', 3, 'Answer', 'm(g+a)'),
    ('a7100000-0000-4000-8000-000000000019', 'a4100000-0000-4000-8000-000000000007', 1, 'Idea', 'Conservative ⇔ path independent ⇔ closed-path work 0.'),
    ('a7100000-0000-4000-8000-000000000020', 'a4100000-0000-4000-8000-000000000007', 2, 'Why', 'Electrostatic and gravity are conservative (in usual intro models).'),
    ('a7100000-0000-4000-8000-000000000021', 'a4100000-0000-4000-8000-000000000007', 3, 'Answer', 'Zero'),
    ('a7100000-0000-4000-8000-000000000022', 'a4100000-0000-4000-8000-000000000008', 1, 'Idea', 'P = dW/dt = F·v.'),
    ('a7100000-0000-4000-8000-000000000023', 'a4100000-0000-4000-8000-000000000008', 2, 'Why', 'Dot product: only the parallel component of F does work.'),
    ('a7100000-0000-4000-8000-000000000024', 'a4100000-0000-4000-8000-000000000008', 3, 'Answer', 'F·v'),
    ('a7100000-0000-4000-8000-000000000025', 'a4100000-0000-4000-8000-000000000009', 1, 'Idea', 'Gaussian surface inside: q_enc = 0 so E = 0.'),
    ('a7100000-0000-4000-8000-000000000026', 'a4100000-0000-4000-8000-000000000009', 2, 'Why', 'Outside it behaves like a point charge.'),
    ('a7100000-0000-4000-8000-000000000027', 'a4100000-0000-4000-8000-000000000009', 3, 'Answer', 'Zero'),
    ('a7100000-0000-4000-8000-000000000028', 'a4100000-0000-4000-8000-000000000010', 1, 'Idea', 'Coulomb force is repulsive for like signs.'),
    ('a7100000-0000-4000-8000-000000000029', 'a4100000-0000-4000-8000-000000000010', 2, 'Why', 'Direction is central, along the line joining charges.'),
    ('a7100000-0000-4000-8000-000000000030', 'a4100000-0000-4000-8000-000000000010', 3, 'Answer', 'Force is along the joining line and repulsive for same sign'),
    ('a7100000-0000-4000-8000-000000000031', 'a4100000-0000-4000-8000-000000000011', 1, 'Idea', 'Charge is conserved so current is the same in series.'),
    ('a7100000-0000-4000-8000-000000000032', 'a4100000-0000-4000-8000-000000000011', 2, 'Why', 'Voltages add to the battery emf.'),
    ('a7100000-0000-4000-8000-000000000033', 'a4100000-0000-4000-8000-000000000011', 3, 'Answer', 'Current'),
    ('a7100000-0000-4000-8000-000000000034', 'a4100000-0000-4000-8000-000000000012', 1, 'Idea', 'ΣI = 0 because charge does not pile up.'),
    ('a7100000-0000-4000-8000-000000000035', 'a4100000-0000-4000-8000-000000000012', 2, 'Why', 'The loop rule is energy per unit charge.'),
    ('a7100000-0000-4000-8000-000000000036', 'a4100000-0000-4000-8000-000000000012', 3, 'Answer', 'Charge conservation'),
    ('a7100000-0000-4000-8000-000000000037', 'a4100000-0000-4000-8000-000000000013', 1, 'Idea', 'Convex (converging) lens: positive focal length in the Cartesian convention used in JEE.'),
    ('a7100000-0000-4000-8000-000000000038', 'a4100000-0000-4000-8000-000000000013', 2, 'Why', 'Concave lens diverges (f < 0).'),
    ('a7100000-0000-4000-8000-000000000039', 'a4100000-0000-4000-8000-000000000013', 3, 'Answer', 'Converging, f > 0'),
    ('a7100000-0000-4000-8000-000000000040', 'a4100000-0000-4000-8000-000000000014', 1, 'Idea', 'sin c = n2/n1 = 1/1.5.'),
    ('a7100000-0000-4000-8000-000000000041', 'a4100000-0000-4000-8000-000000000014', 2, 'Why', 'Light goes glass → air, so n1=1.5, n2=1.'),
    ('a7100000-0000-4000-8000-000000000042', 'a4100000-0000-4000-8000-000000000014', 3, 'Answer', '1/1.5'),
    ('a7100000-0000-4000-8000-000000000043', 'a4100000-0000-4000-8000-000000000015', 1, 'Idea', 'More photons per second → more electrons per second → larger current.'),
    ('a7100000-0000-4000-8000-000000000044', 'a4100000-0000-4000-8000-000000000015', 2, 'Why', 'K_max depends on frequency, not intensity.'),
    ('a7100000-0000-4000-8000-000000000045', 'a4100000-0000-4000-8000-000000000015', 3, 'Answer', 'Photoelectric current'),
    ('a7100000-0000-4000-8000-000000000046', 'a4100000-0000-4000-8000-000000000016', 1, 'Idea', 'φ is the binding energy of the least-bound electron.'),
    ('a7100000-0000-4000-8000-000000000047', 'a4100000-0000-4000-8000-000000000016', 2, 'Why', 'K_max = hν − φ.'),
    ('a7100000-0000-4000-8000-000000000048', 'a4100000-0000-4000-8000-000000000016', 3, 'Answer', 'Minimum energy to emit an electron'),
    ('a7100000-0000-4000-8000-000000000049', 'a4100000-0000-4000-8000-000000000017', 1, 'Idea', 'l = 0,1,2,…,n−1 so 0,1,2 for n=3 (s,p,d).'),
    ('a7100000-0000-4000-8000-000000000050', 'a4100000-0000-4000-8000-000000000017', 2, 'Why', 'l cannot equal n.'),
    ('a7100000-0000-4000-8000-000000000051', 'a4100000-0000-4000-8000-000000000017', 3, 'Answer', '0,1,2'),
    ('a7100000-0000-4000-8000-000000000052', 'a4100000-0000-4000-8000-000000000018', 1, 'Idea', 'At most one electron per unique (n,l,m_l,m_s).'),
    ('a7100000-0000-4000-8000-000000000053', 'a4100000-0000-4000-8000-000000000018', 2, 'Why', 'Two electrons in 1s have opposite spins.'),
    ('a7100000-0000-4000-8000-000000000054', 'a4100000-0000-4000-8000-000000000018', 3, 'Answer', 'Two electrons with all four quantum numbers equal'),
    ('a7100000-0000-4000-8000-000000000055', 'a4100000-0000-4000-8000-000000000019', 1, 'Idea', 'Five bond pairs, no lone pair → TBP.'),
    ('a7100000-0000-4000-8000-000000000056', 'a4100000-0000-4000-8000-000000000019', 2, 'Why', 'PCl3 is pyramidal; SF6 is octahedral.'),
    ('a7100000-0000-4000-8000-000000000057', 'a4100000-0000-4000-8000-000000000019', 3, 'Answer', 'Trigonal bipyramidal'),
    ('a7100000-0000-4000-8000-000000000058', 'a4100000-0000-4000-8000-000000000020', 1, 'Idea', 'Four domains (2 bond + 2 lp) → tetrahedral arrangement, molecular shape bent.'),
    ('a7100000-0000-4000-8000-000000000059', 'a4100000-0000-4000-8000-000000000020', 2, 'Why', 'Oxygen is sp3, not sp.'),
    ('a7100000-0000-4000-8000-000000000060', 'a4100000-0000-4000-8000-000000000020', 3, 'Answer', 'Two lone pairs distort tetrahedral domains'),
    ('a7100000-0000-4000-8000-000000000061', 'a4100000-0000-4000-8000-000000000021', 1, 'Idea', 'Catalysts change rate, not the equilibrium constant.'),
    ('a7100000-0000-4000-8000-000000000062', 'a4100000-0000-4000-8000-000000000021', 2, 'Why', 'ΔG° = −RT ln K is a state function of T, not of path.'),
    ('a7100000-0000-4000-8000-000000000063', 'a4100000-0000-4000-8000-000000000021', 3, 'Answer', 'Does not change K'),
    ('a7100000-0000-4000-8000-000000000064', 'a4100000-0000-4000-8000-000000000022', 1, 'Idea', 'Fewer gas moles on the product side (4 → 2), so high P favours NH3.'),
    ('a7100000-0000-4000-8000-000000000065', 'a4100000-0000-4000-8000-000000000022', 2, 'Why', 'Le Chatelier: system reduces pressure by forming fewer molecules.'),
    ('a7100000-0000-4000-8000-000000000066', 'a4100000-0000-4000-8000-000000000022', 3, 'Answer', 'Favours ammonia'),
    ('a7100000-0000-4000-8000-000000000067', 'a4100000-0000-4000-8000-000000000023', 1, 'Idea', 'Same formula, Cl at different carbons → position isomerism.'),
    ('a7100000-0000-4000-8000-000000000068', 'a4100000-0000-4000-8000-000000000023', 2, 'Why', 'Enantiomers are non-superimposable mirror images.'),
    ('a7100000-0000-4000-8000-000000000069', 'a4100000-0000-4000-8000-000000000023', 3, 'Answer', 'Position isomers'),
    ('a7100000-0000-4000-8000-000000000070', 'a4100000-0000-4000-8000-000000000024', 1, 'Idea', 'Tertiary is most stabilised by alkyl hyperconjugation/induction.'),
    ('a7100000-0000-4000-8000-000000000071', 'a4100000-0000-4000-8000-000000000024', 2, 'Why', 'Methyl has no alkyl donors.'),
    ('a7100000-0000-4000-8000-000000000072', 'a4100000-0000-4000-8000-000000000024', 3, 'Answer', 'Tertiary'),
    ('a7100000-0000-4000-8000-000000000073', 'a4100000-0000-4000-8000-000000000025', 1, 'Idea', 'Bond energy of N≡N is very high.'),
    ('a7100000-0000-4000-8000-000000000074', 'a4100000-0000-4000-8000-000000000025', 2, 'Why', 'P4 has strained P–P bonds and is more reactive in white phosphorus.'),
    ('a7100000-0000-4000-8000-000000000075', 'a4100000-0000-4000-8000-000000000025', 3, 'Answer', 'Strong N≡N triple bond'),
    ('a7100000-0000-4000-8000-000000000076', 'a4100000-0000-4000-8000-000000000026', 1, 'Idea', 'Heavier p-block: ns² electrons remain inert; Bi prefers +3.'),
    ('a7100000-0000-4000-8000-000000000077', 'a4100000-0000-4000-8000-000000000026', 2, 'Why', 'B and C are light.'),
    ('a7100000-0000-4000-8000-000000000078', 'a4100000-0000-4000-8000-000000000026', 3, 'Answer', 'Bismuth'),
    ('a7100000-0000-4000-8000-000000000079', 'a4100000-0000-4000-8000-000000000027', 1, 'Idea', 'Factor (x−1)(x−3)=0.'),
    ('a7100000-0000-4000-8000-000000000080', 'a4100000-0000-4000-8000-000000000027', 2, 'Why', 'Sum 4, product 3.'),
    ('a7100000-0000-4000-8000-000000000081', 'a4100000-0000-4000-8000-000000000027', 3, 'Answer', '1 and 3'),
    ('a7100000-0000-4000-8000-000000000082', 'a4100000-0000-4000-8000-000000000028', 1, 'Idea', 'Negative discriminant → non-real conjugates.'),
    ('a7100000-0000-4000-8000-000000000083', 'a4100000-0000-4000-8000-000000000028', 2, 'Why', 'Equal real needs D=0.'),
    ('a7100000-0000-4000-8000-000000000084', 'a4100000-0000-4000-8000-000000000028', 3, 'Answer', 'Complex conjugates'),
    ('a7100000-0000-4000-8000-000000000085', 'a4100000-0000-4000-8000-000000000029', 1, 'Idea', 'a=3, d=4, a10=3+9×4=39.'),
    ('a7100000-0000-4000-8000-000000000086', 'a4100000-0000-4000-8000-000000000029', 2, 'Why', 'Formula a+(n−1)d.'),
    ('a7100000-0000-4000-8000-000000000087', 'a4100000-0000-4000-8000-000000000029', 3, 'Answer', '39'),
    ('a7100000-0000-4000-8000-000000000088', 'a4100000-0000-4000-8000-000000000030', 1, 'Idea', 'a=1, r=1/2, S=a/(1−r)=2.'),
    ('a7100000-0000-4000-8000-000000000089', 'a4100000-0000-4000-8000-000000000030', 2, 'Why', '|r|<1 is required for convergence.'),
    ('a7100000-0000-4000-8000-000000000090', 'a4100000-0000-4000-8000-000000000030', 3, 'Answer', '2'),
    ('a7100000-0000-4000-8000-000000000091', 'a4100000-0000-4000-8000-000000000031', 1, 'Idea', 'Write (sin 5x)/(5x) × 5 → 1×5=5.'),
    ('a7100000-0000-4000-8000-000000000092', 'a4100000-0000-4000-8000-000000000031', 2, 'Why', 'x must be radians.'),
    ('a7100000-0000-4000-8000-000000000093', 'a4100000-0000-4000-8000-000000000031', 3, 'Answer', '5'),
    ('a7100000-0000-4000-8000-000000000094', 'a4100000-0000-4000-8000-000000000032', 1, 'Idea', 'Power rule n x^{n−1}.'),
    ('a7100000-0000-4000-8000-000000000095', 'a4100000-0000-4000-8000-000000000032', 2, 'Why', 'Integral of x³ is x⁴/4, not the derivative.'),
    ('a7100000-0000-4000-8000-000000000096', 'a4100000-0000-4000-8000-000000000032', 3, 'Answer', '3x²'),
    ('a7100000-0000-4000-8000-000000000097', 'a4100000-0000-4000-8000-000000000033', 1, 'Idea', 'Antiderivative x² from 0 to 1 is 1.'),
    ('a7100000-0000-4000-8000-000000000098', 'a4100000-0000-4000-8000-000000000033', 2, 'Why', 'This is the area of a triangle of base 1 height 2, which is 1.'),
    ('a7100000-0000-4000-8000-000000000099', 'a4100000-0000-4000-8000-000000000033', 3, 'Answer', '1'),
    ('a7100000-0000-4000-8000-000000000100', 'a4100000-0000-4000-8000-000000000034', 1, 'Idea', 'x³ is odd and the interval is symmetric.'),
    ('a7100000-0000-4000-8000-000000000101', 'a4100000-0000-4000-8000-000000000034', 2, 'Why', 'The two areas cancel.'),
    ('a7100000-0000-4000-8000-000000000102', 'a4100000-0000-4000-8000-000000000034', 3, 'Answer', '0'),
    ('a7100000-0000-4000-8000-000000000103', 'a4100000-0000-4000-8000-000000000035', 1, 'Idea', 'Independent ⇒ product 1/6.'),
    ('a7100000-0000-4000-8000-000000000104', 'a4100000-0000-4000-8000-000000000035', 2, 'Why', '5/6 would be a naive union without inclusion-exclusion.'),
    ('a7100000-0000-4000-8000-000000000105', 'a4100000-0000-4000-8000-000000000035', 3, 'Answer', '1/6'),
    ('a7100000-0000-4000-8000-000000000106', 'a4100000-0000-4000-8000-000000000036', 1, 'Idea', 'Definition of conditional probability.'),
    ('a7100000-0000-4000-8000-000000000107', 'a4100000-0000-4000-8000-000000000036', 2, 'Why', 'P(B|A) is the reverse conditional.'),
    ('a7100000-0000-4000-8000-000000000108', 'a4100000-0000-4000-8000-000000000036', 3, 'Answer', 'P(A∩B)/P(B)'),
    ('a7100000-0000-4000-8000-000000000109', 'a4100000-0000-4000-8000-000000000037', 1, 'Idea', 'sin2θ = 1 ⇒ 2θ=90° ⇒ θ=45°.'),
    ('a7100000-0000-4000-8000-000000000110', 'a4100000-0000-4000-8000-000000000037', 2, 'Why', '30° and 60° share a smaller range.'),
    ('a7100000-0000-4000-8000-000000000111', 'a4100000-0000-4000-8000-000000000037', 3, 'Answer', '45°'),
    ('a7100000-0000-4000-8000-000000000112', 'a4100000-0000-4000-8000-000000000038', 1, 'Idea', 'No horizontal force ⇒ no horizontal acceleration.'),
    ('a7100000-0000-4000-8000-000000000113', 'a4100000-0000-4000-8000-000000000038', 2, 'Why', 'Vertical component changes due to gravity.'),
    ('a7100000-0000-4000-8000-000000000114', 'a4100000-0000-4000-8000-000000000038', 3, 'Answer', 'Stays constant'),
    ('a7100000-0000-4000-8000-000000000115', 'a4100000-0000-4000-8000-000000000039', 1, 'Idea', 'v_esc = √(2GM/R), no m of projectile.'),
    ('a7100000-0000-4000-8000-000000000116', 'a4100000-0000-4000-8000-000000000039', 2, 'Why', 'Heavier planets or smaller R increase escape speed.'),
    ('a7100000-0000-4000-8000-000000000117', 'a4100000-0000-4000-8000-000000000039', 3, 'Answer', 'Mass of the escaping body'),
    ('a7100000-0000-4000-8000-000000000118', 'a4100000-0000-4000-8000-000000000040', 1, 'Idea', 'Centripetal acceleration GM/r² toward the planet.'),
    ('a7100000-0000-4000-8000-000000000119', 'a4100000-0000-4000-8000-000000000040', 2, 'Why', 'Speed can be constant while velocity (vector) changes.'),
    ('a7100000-0000-4000-8000-000000000120', 'a4100000-0000-4000-8000-000000000040', 3, 'Answer', 'Direction of velocity changes'),
    ('a7100000-0000-4000-8000-000000000121', 'a4100000-0000-4000-8000-000000000041', 1, 'Idea', 'R ∝ L/A → 2 / (1/2) = 4.'),
    ('a7100000-0000-4000-8000-000000000122', 'a4100000-0000-4000-8000-000000000041', 2, 'Why', 'Resistivity unchanged if temperature is same.'),
    ('a7100000-0000-4000-8000-000000000123', 'a4100000-0000-4000-8000-000000000041', 3, 'Answer', '4 times'),
    ('a7100000-0000-4000-8000-000000000124', 'a4100000-0000-4000-8000-000000000042', 1, 'Idea', '1/Req = 3/R ⇒ Req=R/3.'),
    ('a7100000-0000-4000-8000-000000000125', 'a4100000-0000-4000-8000-000000000042', 2, 'Why', 'Series would be 3R.'),
    ('a7100000-0000-4000-8000-000000000126', 'a4100000-0000-4000-8000-000000000042', 3, 'Answer', 'R/3'),
    ('a7100000-0000-4000-8000-000000000127', 'a4100000-0000-4000-8000-000000000043', 1, 'Idea', 'Diverging (concave) lens.'),
    ('a7100000-0000-4000-8000-000000000128', 'a4100000-0000-4000-8000-000000000043', 2, 'Why', 'Hypermetropia uses convex.'),
